def calculate_F1(x, y, z):
    # Q1: (a, b, c) = (0, 0, 0)
    # F1 = |x+y| + |y+z| + |z+x|
    # Since x, y, z >= 0, this is 2*(x+y+z)
    return 2 * (x + y + z)

def calculate_F2(x, y, z):
    # Q2: (a, b, c) = (9, 9, 9)
    # F2 = |x+y-18| + |y+z-18| + |z+x-18|
    return abs(x + y - 18) + abs(y + z - 18) + abs(z + x - 18)

# Store all unique pairs found
observed_pairs = set()
total_pairs = 0

# Iterate through all 1000 possibilities (0 <= x, y, z <= 9)
for x in range(10):
    for y in range(10):
        for z in range(10):
            total_pairs += 1
            F1 = calculate_F1(x, y, z)
            F2 = calculate_F2(x, y, z)
            pair = (F1, F2)
            observed_pairs.add(pair)

num_unique_pairs = len(observed_pairs)

print(f"Total possible inputs: {total_pairs}")
print(f"Number of unique pairs (F1, F2): {num_unique_pairs}")

if num_unique_pairs < total_pairs:
    print("Duplicate pairs found. Two questions are insufficient.")
else:
    print("No duplicate pairs found among the 1000 inputs.")

